import {useEffect,useRef} from 'react';
import {pushBack,dropBack} from '../services/back-stack.js';

// A window open on screen is closed by the phone's «back» as well as by its own buttons.
// A new `step` (another folder, say) replaces the step instead of adding one.
export default function useBackClose(onClose,active=true,step=null){
  const latest=useRef(onClose);latest.current=onClose;
  useEffect(()=>{if(!active)return;const entry=pushBack(()=>latest.current());return()=>dropBack(entry);},[active,step]);
}
