import React,{useEffect,useLayoutEffect,useRef,useImperativeHandle} from 'react';
import {dateRange,dayLabel,addDays,isDayKey} from '../services/week.js';
import EventList from './EventList.jsx';
import EmptyDay from './EmptyDay.jsx';
import {DayDates} from './ScheduleDate.jsx';
import useHorizontalInertia from './useHorizontalInertia.js';

// The week's two dates, and beside them whether the chosen day is a day off: the same pill turns it into the other kind.
export function WeekDates({start,end,onChange,off=false,onToggleOff}){
  const dates=<DayDates className="m-week-dates" requiredEnd inlineDays start={start} end={end} startLabel="Дата начала" endLabel="Дата конца" onStart={value=>{if(value!==start)onChange({weekStart:value,weekEnd:end>=value?end:addDays(value,6)});}} onEnd={value=>{if(isDayKey(value)&&value>=start&&value!==end)onChange({weekEnd:value});}}/>;
  if(!onToggleOff)return dates;
  return <div className="m-week-top">{dates}<button type="button" className={`m-offday-pill is-compact ${off?'is-off':'is-work'}`} aria-label={off?'Выходной. Сделать рабочим':'Рабочий день. Сделать выходным'} onClick={onToggleOff}><span className="m-offday-word">{off?'Выходной':'Рабочий'}</span></button></div>;
}

// The week's days lie side by side, each a full-width page laid out exactly like a day schedule.
// While a finger moves the pages, onTrack reports their position (in days, fractional) so the day strip moves with them;
// controller.track(position) lets the strip move the pages the same way. The day under the finger becomes the focus once they settle.
// reserve: the height kept free under the pages for the bottom controls, so the empty part of a short day can still be swiped.
export default function ScheduleDays({state,focus,onFocus,onTrack,Icon,onMove,onPlace,onHold,onSwipe,onLoad,enabled=true,controllerRef,inline=null,reserve=0}){
  const root=useRef(null),latest=useRef({onFocus,onTrack,focus,enabled});latest.current={onFocus,onTrack,focus,enabled};
  const driving=useRef(false),touching=useRef(false),slide=useRef(null),settle=useRef(null),shownHeight=useRef('');
  const dates=dateRange(state.weekStart,state.weekEnd),key=dates.join(','),days=useRef(dates);days.current=dates;
  const position=()=>{const node=root.current;return node.scrollLeft/Math.max(1,node.clientWidth);};
  const report=()=>latest.current.onTrack?.(position());
  // The pages are as tall as the day nearest the middle, and reach at least down to the bottom controls.
  const fit=()=>{const node=root.current;if(!node)return;const pages=node.children,page=pages[Math.max(0,Math.min(pages.length-1,Math.round(position())))];if(!page)return;const floor=reserve?window.innerHeight-node.getBoundingClientRect().top-reserve:0,height=Math.ceil(Math.max(page.offsetHeight,floor,160))+'px';if(height!==shownHeight.current){shownHeight.current=height;node.style.height=height;}};
  const stopSlide=()=>{cancelAnimationFrame(slide.current);slide.current=null;if(root.current)root.current.style.scrollSnapType='';};
  const goTo=(day,animate=true)=>{const node=root.current,index=days.current.indexOf(day);if(!node||index<0)return;stopSlide();const from=node.scrollLeft,to=index*node.clientWidth;if(Math.abs(to-from)<1)return;
    if(!animate||window.matchMedia('(prefers-reduced-motion: reduce)').matches){node.scrollLeft=to;report();return;}
    node.style.scrollSnapType='none';const start=performance.now();const step=now=>{const progress=Math.min(1,(now-start)/340),ease=1-Math.pow(1-progress,3);node.scrollLeft=from+(to-from)*ease;report();if(progress<1)slide.current=requestAnimationFrame(step);else stopSlide();};slide.current=requestAnimationFrame(step);};
  const settleSoon=()=>{clearTimeout(settle.current);settle.current=setTimeout(()=>{if(touching.current||slide.current||!driving.current)return;driving.current=false;const day=days.current[Math.round(position())];if(day&&day!==latest.current.focus&&latest.current.enabled)latest.current.onFocus(day);},140);};
  useLayoutEffect(()=>{const node=root.current,index=dates.indexOf(focus);if(index>=0)node.scrollLeft=index*node.clientWidth;report();fit();},[key]);
  // A focus chosen elsewhere (the strip, a template) slides the pages there; one reached by swiping is already in place.
  useEffect(()=>{if(!driving.current)goTo(focus);},[focus]);
  useEffect(()=>{const node=root.current;let frame;
    const scroll=()=>{if(driving.current&&!slide.current)report();cancelAnimationFrame(frame);frame=requestAnimationFrame(fit);settleSoon();};
    const down=()=>{touching.current=true;driving.current=true;stopSlide();node.style.scrollSnapType='';};const up=()=>{touching.current=false;settleSoon();};
    const relayout=()=>{const index=days.current.indexOf(latest.current.focus);if(index>=0&&!driving.current&&!slide.current)node.scrollLeft=index*node.clientWidth;cancelAnimationFrame(frame);frame=requestAnimationFrame(fit);};
    const observer=new ResizeObserver(relayout);observer.observe(node);for(const page of node.children)observer.observe(page);
    node.addEventListener('scroll',scroll,{passive:true});node.addEventListener('touchstart',down,{passive:true});node.addEventListener('touchend',up,{passive:true});node.addEventListener('touchcancel',up,{passive:true});window.addEventListener('scroll',relayout,{passive:true});
    return()=>{observer.disconnect();cancelAnimationFrame(frame);clearTimeout(settle.current);stopSlide();node.removeEventListener('scroll',scroll);node.removeEventListener('touchstart',down);node.removeEventListener('touchend',up);node.removeEventListener('touchcancel',up);window.removeEventListener('scroll',relayout);};
  },[key,reserve]);
  const {stop:stopGlide,...wheel}=useHorizontalInertia(root,{canStart:event=>!event.target.closest('[data-event-id],input,textarea'),onUserScroll:()=>{driving.current=true;stopSlide();}});
  useImperativeHandle(controllerRef,()=>({
    select:day=>goTo(day),
    track(at){const node=root.current;if(!node)return;driving.current=false;stopSlide();node.style.scrollSnapType='none';node.scrollTo({left:at*node.clientWidth,behavior:'instant'});},
  }));
  return <div ref={root} className="m-week-days" aria-label="Дни расписания" {...wheel} onPointerUp={event=>{wheel.onPointerUp(event);if(event.pointerType==='mouse')settleSoon();}}>{dates.map(day=><section key={day} data-week-day={day} aria-label={dayLabel(day)} className={`m-week-day ${focus===day?'is-focused':''} ${state.offDays?.[day]?'is-off':''}`}>
    {!state.schedule.some(item=>item.dayKey===day)&&<EmptyDay off={!!state.offDays?.[day]} onLoad={onLoad&&(()=>onLoad(day))}/>}
    <EventList items={state.schedule.filter(item=>item.dayKey===day)} Icon={Icon} onMove={(id,target)=>onMove(day,id,target)} onPlace={onPlace&&((id,spot)=>onPlace(day,id,spot))} onHold={onHold} onSwipe={onSwipe} enabled={enabled&&focus===day} inline={inline}/>
  </section>)}</div>;
}
