import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import "@fontsource/inter/400.css";
import "@fontsource/inter/500.css";
import "@fontsource/inter/600.css";
import "@fontsource/inter/700.css";
import "./styles.css";
import App from "./App.jsx";
import { appStorage } from "./services/storage.js";
import {initializeImageSizes} from './services/image-sizes.js';
import {initializeFootballGlossary} from './services/football-glossary.js';
import {initializeTeamRoster} from './services/team-roster.js';
import {initializeTemplateFolders} from './services/template-folders.js';
import {appUpdate,SERVICE_WORKER_URL} from './services/app-update.js';
import UpdateNotice from './components/UpdateNotice.jsx';

if('serviceWorker' in navigator&&!import.meta.env.DEV){
  window.addEventListener('load',()=>{navigator.serviceWorker.register(SERVICE_WORKER_URL).catch(()=>{});appUpdate.check({quiet:true});});
  // A home-screen app is usually resumed rather than restarted, so look again whenever it comes back.
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')appUpdate.check({quiet:true});});
  setInterval(()=>appUpdate.check({quiet:true}),30*60*1000);
}

let startupWarning='';

function SaveStatus() {
  const [status, setStatus] = useState(appStorage.getSnapshot());
  useEffect(() => appStorage.subscribe(setStatus), []);
  useEffect(() => {
    const onLeave = (event) => {
      const current = appStorage.getSnapshot();
      if (current.pending || current.failed) {
        event.preventDefault();
        event.returnValue = "";
      }
    };
    window.addEventListener("beforeunload", onLeave);
    return () => window.removeEventListener("beforeunload", onLeave);
  }, []);
  if (!status.error && !status.failed) return null;
  return (
    <div
      role="status"
      aria-live="polite"
      style={{
        position: "fixed",
        bottom: 12,
        left: 16,
        zIndex: 1000,
        fontSize: 12,
        color: status.error ? "#991b1b" : "#71717a",
        background: "#fff",
        padding: "6px 10px",
        borderRadius: 6,
        maxWidth: 480,
      }}
    >
      {status.pending ? "Сохраняется…" : status.error || "Сохранено в браузере"}
      {!status.pending && status.failed > 0 && (
        <button
          onClick={() => appStorage.retry()}
          style={{ marginLeft: 8, textDecoration: "underline" }}
        >
          Повторить
        </button>
      )}
    </div>
  );
}

function ErrorNotice() {
  const [message, setMessage] = useState(startupWarning);
  useEffect(() => {
    const onError = (event) => setMessage(event.detail);
    window.addEventListener("schedule-error", onError);
    return () => window.removeEventListener("schedule-error", onError);
  }, []);
  if (!message) return null;
  return (
    <div
      role="alert"
      style={{
        position: "fixed",
        bottom: 20,
        right: 20,
        zIndex: 1000,
        maxWidth: 420,
        padding: 16,
        border: "1px solid #dc2626",
        borderRadius: 8,
        background: "#fff",
        color: "#991b1b",
      }}
    >
      {message}
      <button onClick={() => setMessage("")} style={{ marginLeft: 12 }}>
        Закрыть
      </button>
    </div>
  );
}
const root = createRoot(document.getElementById("root"));
root.render(<p style={{ padding: 24 }}>Загружаем сохранённые расписания…</p>);
appStorage
  .initialize()
  .then(async()=>{try{await initializeTeamRoster(appStorage);await initializeTemplateFolders(appStorage);await initializeImageSizes(appStorage);await initializeFootballGlossary(appStorage);}catch{startupWarning='Не удалось добавить стартовые шаблоны: недостаточно места или браузер запретил запись. Ваши данные доступны; повторите запуск после освобождения места.';}})
  .then(() =>
    root.render(
      <>
        <ErrorNotice />
        <SaveStatus />
        <UpdateNotice />
        <App />
      </>,
    ),
  )
  .catch(() => {
    root.render(
      <div role="alert" style={{ padding: 24 }}>
        Не удалось открыть сохранённые данные. Закройте другие вкладки
        приложения и повторите загрузку. Существующие данные не изменены.{" "}
        <button onClick={() => location.reload()}>Повторить</button>
      </div>,
    );
  });
