const fold=text=>text.normalize('NFKC').toLocaleLowerCase('ru').replaceAll('ё','е');
const escape=text=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
export function replacePhrases(text,entries){
  const terms=new Map();for(const entry of entries)for(const term of entry.terms)if(term.trim()&&!terms.has(fold(term.trim())))terms.set(fold(term.trim()),entry.value);
  if(!terms.size)return {text,unknown:text};
  const pattern=new RegExp('(?<![\\p{L}\\p{N}_])(?:'+[...terms.keys()].sort((a,b)=>b.length-a.length).map(term=>escape(term).replaceAll('е','[её]')).join('|')+')(?![\\p{L}\\p{N}_])','giu');
  let unknown='',previous=0;
  const translated=text.replace(pattern,(match,offset)=>{unknown+=text.slice(previous,offset);previous=offset+match.length;return terms.get(fold(match));});
  unknown+=text.slice(previous);return {text:translated,unknown};
}

