const targetIndex={en:1,es:2,fr:3,de:4,ja:5,zh:6};
export function offlineTranslate(text,language,templates,englishContext){
  if(language==='ru')return {text,complete:true};
  const rules=activeGlossary(templates),tokens=[];
  const direct=englishContext?{text,unknown:text}:replacePhrases(text,rules.filter(rule=>rule.language===language).map(rule=>{const token=`\uE000${tokens.length}\uE001`;tokens.push(rule.translation);return {terms:[rule.source,...rule.aliases],value:token};}));
  const glossary=rules.filter(rule=>rule.language==='en').map(rule=>({terms:[rule.source,...rule.aliases],value:rule.translation}));
  const pivot=englishContext?{text:englishContext,unknown:''}:replacePhrases(direct.text,[...glossary,...vocabulary.filter(row=>row[0]).map(row=>({terms:row[0].split('|'),value:row[1]}))]);
  const expand=value=>value.replace(/\uE000(\d+)\uE001/g,(_,index)=>tokens[Number(index)]);
  if(language==='en')return {text:expand(pivot.text),complete:!/[\p{L}]/u.test(pivot.unknown)};
  const index=targetIndex[language];if(!index)return {text,complete:false};
  const result=replacePhrases(pivot.text,vocabulary.map(row=>({terms:[row[1]],value:row[index]})));
  return {text:expand(result.text),complete:!/[\p{L}]/u.test(pivot.unknown+result.unknown)};
}

const fingerprint=templates=>JSON.stringify(activeGlossary(templates));
export const memoryKey=(text,lang,templates,englishContext='',context='')=>JSON.stringify([text,lang,fingerprint(templates),englishContext,context]);
export async function translateSchedule({items,targetLangs,templates,apiKeys,model,memory={},online=true,request,context='',provider='gemini'}){
  const result={},meta={},nextMemory={...memory},langs=[...new Set(['en',...targetLangs])];
  const pending=[];let offline=provider!=='local'&&(!online||!apiKeys.length),incomplete=0,cached=0,reason=!online?'Нет интернета.':!apiKeys.length?'API ключ не добавлен.':'';
  for(const item of items){
    if(!item.description?.trim())continue;
    result[item.id]={};meta[item.id]={};
    const english=item.translationMeta?.en?.manual&&item.translationMeta.en.source===item.description?item.translations?.en:undefined;
    for(const lang of langs){const manual=item.translationMeta?.[lang];if(manual?.manual&&manual.source===item.description&&typeof item.translations?.[lang]==='string'){result[item.id][lang]=item.translations[lang];meta[item.id][lang]=manual;}}
    if(langs.some(lang=>result[item.id][lang]===undefined))pending.push({id:item.id,text:item.description,englishContext:english});
  }
  if(!offline&&pending.length){
    try{
      const translated=await request({items:pending,targetLangs:langs,glossary:activeGlossary(templates),apiKeys,model,context});
      for(const item of pending)for(const lang of langs){
        const value=translated[item.id]?.[lang];if(typeof value!=='string')throw Error('Нейросеть перевела не все события. Попробуйте ещё раз.');
        if(result[item.id][lang]!==undefined)continue;
        result[item.id][lang]=value;meta[item.id][lang]={source:item.text,mode:provider};
        nextMemory[memoryKey(item.text,lang,templates,item.englishContext,context)]={text:value};
      }
    }catch(error){if(provider==='local'||error.code!=='NETWORK_UNAVAILABLE'&&error.name!=='TypeError')throw error;offline=true;reason='Gemini недоступен. Перевод выполнен локально.';}
  }
  if(offline)for(const item of pending)for(const lang of langs){
    if(result[item.id][lang]!==undefined)continue;
    const cachedValue=memory[memoryKey(item.text,lang,templates,item.englishContext,context)],saved=typeof cachedValue?.text==='string'?cachedValue:null;
    const translated=saved?{text:saved.text,complete:true}:offlineTranslate(item.text,lang,templates,item.englishContext);
    if(saved)cached++;if(!translated.complete&&targetLangs.includes(lang))incomplete++;
    result[item.id][lang]=translated.text;meta[item.id][lang]={source:item.text,mode:saved?'cache':'dictionary',incomplete:!translated.complete};
  }
  return {translations:result,meta,memory:Object.fromEntries(Object.entries(nextMemory).slice(-500)),mode:offline?'offline':provider,incomplete,cached,reason:offline?reason:''};
}
export function mergeTranslations(schedule,response,sources){
  return schedule.map(item=>{if(item.description!==sources.get(item.id)||!response.translations[item.id])return item;const translations={...item.translations},translationMeta={...item.translationMeta};for(const [lang,text] of Object.entries(response.translations[item.id])){if(item.translationMeta?.[lang]?.manual&&item.translationMeta[lang].source===item.description&&typeof item.translations?.[lang]==='string')continue;translations[lang]=text;translationMeta[lang]=response.meta[item.id][lang];}return {...item,translations,translationMeta};});
}
