export const STORAGE_KEYS = [
  "multiScheduleState",
  "savedEvents",
  "savedTemplates",
  "geminiAiConfig",
  "mobileEditorPreferences",
  "translationTemplates",
  "translationMemory",
  "teamTemplates",
  "teamRosterVersion",
  "templateFoldersVersion",
  "sizeTemplates",
  "imageSizesVersion",
  "footballGlossaryVersion",
  "translationContext",
  "standardTemplateSeeded",
  "defaultModelFlash",
];

function transactionResult(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onabort = () =>
      reject(transaction.error || Error("Запись отменена браузером."));
    transaction.onerror = () => {}; // onabort reports the final transaction result.
  });
}

export function createAppStorage({
  indexedDB,
  legacyStorage,
  databaseName = "multischedule-local",
} = {}) {
  const cache = new Map(),
    listeners = new Set(),
    writeListeners = new Set(),
    failed = new Map();
  let database,
    tail = Promise.resolve(),
    pending = 0,
    lastError = "";
  const snapshot = () => ({ pending, error: lastError, failed: failed.size });
  const notify = () => {
    for (const listener of listeners) listener(snapshot());
  };
  const persist = async (key, value) => {
    if (database) {
      const transaction = database.transaction("documents", "readwrite");
      const finished = transactionResult(transaction);
      transaction.objectStore("documents").put(value, key);
      await finished;
    } else {
      if (!legacyStorage) throw Error("Браузер запретил доступ к хранилищу.");
      legacyStorage.setItem(key, value);
    }
  };
  return {
    async initialize() {
      if (indexedDB) {
        database = await new Promise((resolve, reject) => {
          const request = indexedDB.open(databaseName, 1);
          request.onupgradeneeded = () =>
            request.result.createObjectStore("documents");
          request.onerror = () => reject(request.error);
          request.onblocked = () =>
            reject(
              Error("Закройте другие вкладки приложения и повторите загрузку."),
            );
          request.onsuccess = () => resolve(request.result);
        });
        database.onversionchange = () => database.close();
        const transaction = database.transaction("documents", "readonly");
        const finished = transactionResult(transaction);
        for (const key of STORAGE_KEYS) {
          const request = transaction.objectStore("documents").get(key);
          request.onsuccess = () => {
            if (request.result !== undefined) cache.set(key, request.result);
          };
        }
        await finished;
      }
      // Migrate each key independently. Keep the old copy until the new write commits.
      for (const key of STORAGE_KEYS) {
        if (cache.has(key)) continue;
        let value;
        try {
          value = legacyStorage?.getItem(key);
        } catch {}
        if (value == null) continue;
        if (database) await persist(key, value);
        cache.set(key, value);
      }
    },
    getItem: (key) => cache.get(key) ?? null,
    setItem(key, value) {
      const saved = String(value);
      pending++;
      notify();
      const operation = tail.catch(() => {}).then(() => persist(key, saved));
      tail = operation;
      return operation
        .then(
          () => {
            cache.set(key, saved);
            failed.delete(key);
            if (database) {
              try {
                legacyStorage?.removeItem(key);
              } catch {}
            }
            if (!failed.size) lastError = "";
            for (const listener of writeListeners) listener(key, saved);
          },
          (error) => {
            failed.set(key, saved);
            lastError =
              "Не удалось сохранить данные в браузере. Проверьте свободное место и разрешения, затем нажмите «Повторить». " +
              (error.name === "QuotaExceededError"
                ? "Хранилище заполнено."
                : "");
            throw Error(lastError, { cause: error });
          },
        )
        .finally(() => {
          pending--;
          notify();
        });
    },
    setItems(entries) {
      const saved=Object.fromEntries(Object.entries(entries).map(([key,value])=>[key,String(value)]));
      pending++;notify();
      const operation=tail.catch(()=>{}).then(async()=>{
        if(database){const transaction=database.transaction('documents','readwrite'),finished=transactionResult(transaction);for(const [key,value] of Object.entries(saved))transaction.objectStore('documents').put(value,key);await finished;}
        else{if(!legacyStorage)throw Error('Браузер запретил доступ к хранилищу.');const before=Object.fromEntries(Object.keys(saved).map(key=>[key,legacyStorage.getItem(key)]));try{for(const [key,value] of Object.entries(saved))legacyStorage.setItem(key,value);}catch(error){for(const key of Object.keys(before))legacyStorage.removeItem(key);for(const [key,value] of Object.entries(before)){if(value!=null)legacyStorage.setItem(key,value);}throw error;}}
        for(const [key,value] of Object.entries(saved)){cache.set(key,value);failed.delete(key);if(database){try{legacyStorage?.removeItem(key);}catch{}}for(const listener of writeListeners)listener(key,value);}
        if(!failed.size)lastError='';
      });
      tail=operation;
      return operation.catch(error=>{throw Error('Не удалось загрузить шаблоны. Прежние данные сохранены. Проверьте место в хранилище и повторите загрузку.',{cause:error});}).finally(()=>{pending--;notify();});
    },
    // Everything the app keeps is removed at once, here and in the old storage; the next start is a first start.
    async clear() {
      await tail.catch(() => {});
      if (database) {
        const transaction = database.transaction("documents", "readwrite");
        const finished = transactionResult(transaction);
        transaction.objectStore("documents").clear();
        await finished;
      }
      for (const key of STORAGE_KEYS) {
        try {
          legacyStorage?.removeItem(key);
        } catch {}
      }
      cache.clear();
      failed.clear();
      lastError = "";
      notify();
    },
    retry() {
      return Promise.allSettled(
        [...failed].map(([key, value]) => this.setItem(key, value)),
      );
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    subscribeWrites(listener) {
      writeListeners.add(listener);
      return () => writeListeners.delete(listener);
    },
    getSnapshot: snapshot,
    async close() {
      await tail.catch(() => {});
      database?.close();
    },
  };
}

let legacyStorage;
try {
  legacyStorage = globalThis.localStorage;
} catch {}
export const appStorage = createAppStorage({
  indexedDB: globalThis.indexedDB,
  legacyStorage,
});

export function readStoredJson(key, fallback, validate = () => true) {
  const raw = appStorage.getItem(key);
  if (raw == null) return fallback;
  try {
    const value = JSON.parse(raw);
    if (!validate(value)) throw Error("Invalid data");
    return value;
  } catch {
    window.dispatchEvent(
      new CustomEvent("schedule-error", {
        detail:
          "Не удалось прочитать часть данных (" +
          key +
          "). Остальная библиотека загружена.",
      }),
    );
    return fallback;
  }
}
