export const GLOSSARY_LANGUAGES=['en','es','fr','de','ja','zh'];
export const ruleLanguage=rule=>rule.language??'en';
export const ruleTranslation=rule=>rule.translation??rule.english??'';
// A changed word starts the rule afresh; the English translation is also kept under its older field name.
export function patchRule(rule,patch){
  const next={...rule,...patch};
  if('source' in patch&&patch.source.trim().toLocaleLowerCase('ru')!==(rule.source||'').trim().toLocaleLowerCase('ru'))next.aliases=[];
  if('translation' in patch||'language' in patch){const translation=ruleTranslation(next);next.translation=translation;next.english=ruleLanguage(next)==='en'?translation:undefined;}
  return next;
}
export const validTranslationRule=rule=>rule&&typeof rule.id==='string'&&typeof rule.source==='string'&&typeof (rule.translation??rule.english)==='string'&&GLOSSARY_LANGUAGES.includes(ruleLanguage(rule))&&(!rule.aliases||Array.isArray(rule.aliases)&&rule.aliases.every(alias=>typeof alias==='string'));
export function glossaryRules(templates){return templates.filter(rule=>rule.kind!=='folder'&&rule.enabled!==false&&rule.source?.trim()&&ruleTranslation(rule).trim()).map(rule=>({source:rule.source,language:ruleLanguage(rule),translation:ruleTranslation(rule),...(ruleLanguage(rule)==='en'?{english:ruleTranslation(rule)}:{}),aliases:rule.aliases||[],context:rule.context||''}));}
