import React,{useEffect,useRef,useState} from 'react';
import EditorIcon from './EditorIcon.jsx';
import {dayLabel,isDayKey} from '../services/week.js';

export function DayDates({start,end,onStart,onEnd,requiredEnd=false,inlineDays=false,className='',startLabel='Дата расписания',endLabel='Вторая дата расписания'}){
  const [second,setSecond]=useState(requiredEnd||!!end),[draft,setDraft]=useState(start),[draftEnd,setDraftEnd]=useState(end||'');
  useEffect(()=>setDraft(start),[start]);useEffect(()=>{setDraftEnd(end||'');setSecond(requiredEnd||!!end);},[end,requiredEnd]);
  const commitStart=value=>{setDraft(value);if(isDayKey(value)&&value!==start)onStart(value);};
  const commitEnd=value=>{setDraftEnd(value);if(isDayKey(value)&&value>=start)onEnd(value);else if(!value)onEnd(null);};
  const weekday=(date,form='long')=>new Intl.DateTimeFormat('ru-RU',{weekday:form}).format(new Date(`${date}T12:00:00`));
  // A week's two dates carry their weekday inside the field, at its right («ПН», «ВС»), so no caption line sits above them.
  if(inlineDays)return <div className={`m-day-dates is-inline-days ${className}`}>
    <div className="m-date-box"><input type="date" aria-label={`${startLabel}, ${weekday(start)}`} value={draft} onInput={event=>setDraft(event.currentTarget.value)} onChange={event=>commitStart(event.currentTarget.value)} onBlur={event=>commitStart(event.currentTarget.value)}/><span className="m-date-day" aria-hidden="true">{weekday(start,'short')}</span></div>
    <div className="m-date-box"><input type="date" min={start} aria-label={`${endLabel}${end?`, ${weekday(end)}`:''}`} value={draftEnd} onInput={event=>setDraftEnd(event.currentTarget.value)} onChange={event=>commitEnd(event.currentTarget.value)} onBlur={event=>commitEnd(event.currentTarget.value)}/>{end&&<span className="m-date-day" aria-hidden="true">{weekday(end,'short')}</span>}</div>
  </div>;
  return <div className={`m-day-dates ${className}`}><div className="m-day-date-field"><div className="m-date-heading"><span className="m-date-weekday">{weekday(start)}</span></div><input type="date" aria-label={startLabel} value={draft} onInput={event=>setDraft(event.currentTarget.value)} onChange={event=>commitStart(event.currentTarget.value)} onBlur={event=>commitStart(event.currentTarget.value)}/></div>
    {second?<div className="m-second-date"><div className="m-date-heading"><span className="m-date-weekday">{end?weekday(end):'Вторая дата'}</span></div><div className={`m-second-date-input ${requiredEnd?'':'has-remove'}`}><input type="date" min={start} aria-label={endLabel} value={draftEnd} onInput={event=>setDraftEnd(event.currentTarget.value)} onChange={event=>commitEnd(event.currentTarget.value)} onBlur={event=>commitEnd(event.currentTarget.value)}/>{!requiredEnd&&<button type="button" className="m-remove-date" aria-label="Убрать вторую дату" onClick={()=>{setSecond(false);setDraftEnd('');onEnd(null);}}><EditorIcon name="close"/></button>}</div></div>:<button type="button" className="m-second-date-add" onClick={()=>setSecond(true)}>Вторая дата</button>}
  </div>;
}

export default function FloatingScheduleDate({weekly,focus,start,end}){
  const [visible,setVisible]=useState(false),root=useRef(null);
  useEffect(()=>{let frame;const measure=()=>{const anchor=document.querySelector(weekly?'.m-week-day.is-focused>header':'.m-day-dates');setVisible(!!anchor&&anchor.getBoundingClientRect().bottom<=8);};const update=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(measure);};window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);const observer=new ResizeObserver(update);if(root.current?.parentElement)observer.observe(root.current.parentElement);measure();return()=>{cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('scroll',update);window.removeEventListener('resize',update);};},[weekly,focus,start,end]);
  const date=weekly?focus:start;
  return <div ref={root} className={`m-floating-date ${visible?'is-visible':''}`} aria-hidden={!visible}>{date&&dayLabel(date,true)}{!weekly&&end&&end!==start?` - ${dayLabel(end,true)}`:''}</div>;
}
