import React from 'react';
import {calendarWeeks,dayLabel} from '../services/week.js';
import {EVENT_COLORS,eventTime,pictureStyle} from '../services/editor.js';
import GameMatch from './GameMatch.jsx';
import {sideBySide} from './ExportRows.jsx';

export default function WeeklyPreview({state,Icon,languages=[],translationMode='inline'}){
  return <div className="m-week-calendar"><header><h1>{state.cardTitle}</h1><p>{state.weekStart.split('-').reverse().join('.')} — {state.weekEnd.split('-').reverse().join('.')}</p></header><div className="m-calendar-weekdays">{['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(day=><strong key={day}>{day}</strong>)}</div>{calendarWeeks(state.weekStart,state.weekEnd).map((week,index)=><div key={index} className="m-calendar-week">{week.map((day,column)=><section key={day||column} className={`m-calendar-day ${!day?'is-outside':''} ${state.offDays?.[day]?'is-off':''} ${state.schedule.some(item=>item.dayKey===day)?'has-events':''}`}>
    {day&&<><h2>{new Date(`${day}T12:00:00`).getDate()}<small>{dayLabel(day,true).split(',')[0]}</small></h2>{state.offDays?.[day]&&<strong className="m-calendar-off">Выходной</strong>}{(items=>sideBySide(items,items.map(item=><div key={item.id} data-type={item.type} className={`m-calendar-event ${item.type==='game'?'is-game':''}`} style={{background:item.type==='image'?'transparent':EVENT_COLORS[item.color]?.[1]||'transparent'}}>{item.type==='image'?(item.image&&<img className="m-calendar-picture" src={item.image} alt="" style={pictureStyle(item)}/>):item.type==='game'?<>{eventTime(item)&&<b>{eventTime(item)}</b>}<div><GameMatch item={item} compact/></div></>:<><div className="m-calendar-event-head">{item.icon&&<span className="m-calendar-event-icon"><Icon icon={item.icon}/></span>}{eventTime(item)?<b>{eventTime(item)}</b>:<span>{item.description}</span>}</div>{eventTime(item)&&<div className="m-calendar-event-description">{item.description}</div>}</>}{languages.filter(code=>item.translations?.[code]).length>0&&<small className={translationMode==='inline'?'is-inline':''}>{languages.filter(code=>item.translations?.[code]).map(code=>item.translations[code]).join(' / ')}</small>}</div>)))(state.schedule.filter(item=>item.dayKey===day))}</>}
  </section>)}</div>)}</div>;
}
