import React,{useEffect,useLayoutEffect,useRef} from 'react';
import {createPortal} from 'react-dom';
import {hapticTick} from '../services/wheel.js';
import useScrollLock from './useScrollLock.js';
import useMouseDrum from './useMouseDrum.js';

const ITEM=44,ROWS=5,HEIGHT=ITEM*ROWS;

// One vertical drum; the value under the frame's middle band is the chosen one.
function Column({items,value,onChange,label,width,onPick}){
  const root=useRef(null),timer=useRef(null),last=useRef(value),latest=useRef({value,onChange});latest.current={value,onChange};
  const index=Math.max(0,items.findIndex(item=>item.value===value));
  useLayoutEffect(()=>{root.current.scrollTop=index*ITEM;},[]);
  useEffect(()=>()=>clearTimeout(timer.current),[]);
  // A mouse drags the drum or turns it a face per notch; it always comes to rest on a face, and the value follows from the scrolling.
  const aim=useRef(null);
  const land=at=>{const node=root.current,face=Math.max(0,Math.min(items.length-1,at));aim.current=face;node.scrollTo({top:face*ITEM,behavior:'smooth'});};
  useMouseDrum(root,{axis:'y',onDrag:()=>{aim.current=null;},onRelease:offset=>land(Math.round(offset/ITEM)),onStep:direction=>land((aim.current??Math.round(root.current.scrollTop/ITEM))+direction)});
  const scroll=()=>{
    const node=root.current,at=Math.max(0,Math.min(items.length-1,Math.round(node.scrollTop/ITEM)));
    if(items[at].value!==last.current){last.current=items[at].value;hapticTick();}
    clearTimeout(timer.current);
    timer.current=setTimeout(()=>{aim.current=null;const next=items[at].value;if(next!==latest.current.value)latest.current.onChange(next);},110);
  };
  return <div ref={root} data-scroll-allow className="m-wheel-column" role="listbox" aria-label={label} style={{width,height:HEIGHT,paddingBlock:(HEIGHT-ITEM)/2}} onScroll={scroll}>
    {items.map((item,at)=><button type="button" role="option" key={item.value} aria-selected={item.value===value} aria-label={item.label} className={`m-wheel-option ${item.className||''}`} style={{height:ITEM}} onClick={()=>{if(item.value===value&&Math.abs(root.current.scrollTop-at*ITEM)<4)onPick();else{root.current.scrollTo({top:at*ITEM,behavior:'smooth'});}}}>{item.content??item.label}</button>)}
  </div>;
}

// A tap beside an open drum or palette only closes it: it closes on the click, so the tap never reaches what lies underneath.
// A palette with every option in view, opened next to the tapped part of a card; one tap picks and closes.
export function ChoiceOverlay({anchor,label,items,value,onChange,onClose}){
  const latest=useRef(onClose);latest.current=onClose;
  const columns=Math.min(6,items.length),width=columns*48+(columns-1)*6+20,height=Math.ceil(items.length/columns)*54+14;
  const left=Math.max(8,Math.min(window.innerWidth-width-8,anchor.left+anchor.width/2-width/2));
  const below=anchor.bottom+6,top=below+height<=window.innerHeight-8?below:Math.max(8,anchor.top-6-height);
  useScrollLock();
  useEffect(()=>{const key=event=>{if(event.key==='Escape'){event.preventDefault();latest.current();}};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key);},[]);
  return createPortal(<div className="m-wheel-overlay">
    <div className="m-wheel-backdrop" onPointerDown={event=>event.preventDefault()} onClick={()=>latest.current()}/>
    <div data-scroll-allow className="m-choice-sheet" role="listbox" aria-label={label} style={{left,top,width,gridTemplateColumns:`repeat(${columns},48px)`}}>
      {items.map(item=><button type="button" role="option" key={item.value} aria-selected={item.value===value} aria-label={item.label} title={item.label} className="m-choice-option" onClick={()=>{if(item.value!==value)onChange(item.value);latest.current();}}>{item.content??item.label}</button>)}
    </div>
  </div>,document.body);
}

// A framed drum laid over the tapped part of a card, reaching above and below it.
export default function WheelOverlay({anchor,columns,onClose}){
  const width=columns.reduce((sum,column)=>sum+column.width,0)+4;
  const left=Math.max(8,Math.min(window.innerWidth-width-8,anchor.left+anchor.width/2-width/2));
  const top=Math.max(8,Math.min(window.innerHeight-HEIGHT-12,anchor.top+anchor.height/2-HEIGHT/2));
  const latest=useRef(onClose);latest.current=onClose;
  useScrollLock();
  useEffect(()=>{const key=event=>{if(['Escape','Enter'].includes(event.key)){event.preventDefault();latest.current();}};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key);},[]);
  return createPortal(<div className="m-wheel-overlay">
    <div className="m-wheel-backdrop" onPointerDown={event=>event.preventDefault()} onClick={()=>latest.current()}/>
    <div className="m-wheel-frame-v" style={{left,top,width,height:HEIGHT+4}}>
      <span className="m-wheel-band" style={{top:(HEIGHT-ITEM)/2+2,height:ITEM}} aria-hidden="true"/>
      {columns.map((column,index)=><Column key={column.label||index} {...column} onPick={()=>latest.current()}/>)}
    </div>
  </div>,document.body);
}
