import {replacePhrases} from './translation.js';

export const LOCAL_MODEL={id:'onnx-community/Qwen3-0.6B-ONNX',revision:'58ca03a5e7b354b480b1a82b34bde8dc7b854cc0',name:'Qwen3 · На устройстве'};
export const LOCAL_MODEL_CACHE='schedule-local-ai-qwen3-v1';
export const aiProvider=config=>config.provider==='local'||config.provider==='gemini'?config.provider:config.apiKeys?.length?'gemini':'local';
const languageNames={en:'English',es:'Spanish',fr:'French',de:'German',ja:'Japanese',zh:'Simplified Chinese',ru:'Russian'};
const fold=value=>value.normalize('NFKC').toLocaleLowerCase('ru').replaceAll('ё','е');

export function relevantGlossary(text,rules=[]){
  // Keep every language variant of a relevant word, including its sense notes.
  const selected=new Set(rules.filter(rule=>replacePhrases(text,[{terms:[rule.source,...(rule.aliases||[])],value:''}]).text!==text).map(rule=>fold(rule.source)));
  return rules.filter(rule=>selected.has(fold(rule.source))).map(({source,language,translation,english,context})=>({source,language:language||'en',translation:translation??english,context:context||''}));
}

export function exactGlossaryTranslation(text,language,rules=[]){
  const entries=rules.filter(rule=>rule.enabled!==false&&(rule.language||'en')===language).map(rule=>({terms:[rule.source,...(rule.aliases||[])],value:rule.translation??rule.english}));
  const result=replacePhrases(text,entries);
  return /[\p{L}]/u.test(result.unknown)?null:result.text;
}

export function readLocalJson(text){
  const clean=String(text).replace(/<think>[\s\S]*?<\/think>/g,'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
  const array=clean.startsWith('['),start=clean.indexOf(array?'[':'{'),end=clean.lastIndexOf(array?']':'}');
  if(start<0||end<start)throw Error('Модель не смогла собрать расписание. Уточните текст и повторите.');
  try{const value=JSON.parse(clean.slice(start,end+1));return Array.isArray(value)?{schedule:value}:value;}catch{throw Error('Модель вернула незавершённый ответ. Разделите текст на меньшие части.');}
}

const validTime=value=>typeof value==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(value);
const normalizeTime=value=>String(value??'').trim().replace(/^(\d)[:.]/,'0$1:').replace('.',':');
export function normalizeLocalSchedule(value,source){
  if(!value||!Array.isArray(value.schedule)||!value.schedule.length||value.schedule.length>60)throw Error('Модель не нашла события. Добавьте время и описание событий в текст.');
  const sourceTimes=new Set([...source.matchAll(/(?<!\d)(\d{1,2})[:.](\d{2})(?!\d)/g)].map(match=>`${match[1].padStart(2,'0')}:${match[2]}`));
  const schedule=value.schedule.map(item=>{
    if(!item||typeof item.description!=='string'||!item.description.trim()||item.description.length>2000)throw Error('Модель вернула событие без корректного описания. Повторите запрос.');
    const comparable=text=>fold(text).replace(/[^\p{L}\p{N}]/gu,'');
    if(!comparable(source).includes(comparable(item.description)))throw Error('Модель добавила текст, которого нет в исходном расписании. Уточните текст и повторите.');
    const embeddedTimes=[...String(item.time??'').matchAll(/(?<!\d)\d{1,2}[:.]\d{2}(?!\d)/g)].map(match=>normalizeTime(match[0]));
    let type=embeddedTimes.length===2?'range':['timed','range','untimed','h1','h2','h3','comment'].includes(item.type)?item.type:item.time?'timed':'untimed';
    let time=embeddedTimes.length===2?embeddedTimes[0]:normalizeTime(item.time),endTime=embeddedTimes.length===2?embeddedTimes[1]:normalizeTime(item.endTime);
    const lines=source.split('\n').filter(line=>comparable(line).includes(comparable(item.description)));
    let description=item.description.trim();
    const prefix=/^\s*(?:(?:в|с)\s+)?\d{1,2}[:.]\d{2}(?:\s*(?:[-–—]|до)\s*\d{1,2}[:.]\d{2})?\s*[-–—:]?\s*/iu;
    if(lines.length===1&&prefix.test(lines[0])){
      const clocks=[...lines[0].matchAll(/(?<!\d)\d{1,2}[:.]\d{2}(?!\d)/g)].map(match=>normalizeTime(match[0]));
      // A clear source line is authoritative for interval versus single time.
      if(clocks.length===1){type='timed';if(!time)time=clocks[0];}
      if(clocks.length===2){type='range';if(!time)time=clocks[0];if(!endTime)endTime=clocks[1];}
      description=description.replace(prefix,'').trim();
    }
    const timed=['timed','range'].includes(type);
    if(timed&&(!validTime(time)||!sourceTimes.has(time)))throw Error(`Модель вернула время «${String(item.time??'').slice(0,80)}», которого нет в тексте. Укажите время в формате 09:00 и повторите.`);
    if(type==='range'&&(!validTime(endTime)||!sourceTimes.has(endTime)))throw Error('Не удалось определить окончание события. Укажите оба времени и повторите.');
    if(!description)throw Error('Модель не определила название события. Уточните исходный текст.');
    return {type,time:timed?time:'',...(type==='range'?{endTime}:{}),description};
  });
  const retainedTimes=new Set(schedule.flatMap(item=>[item.time,item.endTime].filter(Boolean)));
  if([...sourceTimes].some(time=>!retainedTimes.has(time)))throw Error('Модель пропустила часть времени. Разделите текст на отдельные строки с событиями и повторите.');
  return {cardTitle:'Расписание на день',schedule};
}

export function splitScheduleText(text){
  if(typeof text!=='string'||!text.trim())throw Error('Введите текст расписания.');
  if(text.length>12000)throw Error('Для локальной модели вставьте до 12 000 символов за один раз.');
  const chunks=[];let chunk='';
  for(const line of text.trim().split(/\n+/)){
    if(line.length>1600)throw Error('Разделите длинный текст на строки с отдельными событиями.');
    if(chunk&&(chunk.length+line.length>1600||chunk.split('\n').length>=8)){chunks.push(chunk);chunk='';}
    chunk+=(chunk?'\n':'')+line;
  }
  if(chunk)chunks.push(chunk);return chunks;
}

export async function runLocalTask(action,input,{generate,onProgress=()=>{}}){
  if(action==='parseScheduleFromText'){
    const chunks=splitScheduleText(input.text),schedule=[];
    for(let index=0;index<chunks.length;index++){
      onProgress({message:`Составляем расписание: ${index+1} из ${chunks.length}`});
      const output=await generate([
        {role:'system',content:'Extract ALL events from the user text into a football team schedule. Return ONLY a JSON object with key "schedule" containing an array. Each event has "description" (verbatim original Russian event text), "type" ("timed" for one time, "range" for two times, "untimed" for no time), "time" (HH:mm or empty string). Ranges also have "endTime" (HH:mm). Preserve exact times and original descriptions. Never invent, omit or translate events. No markdown, no explanation. /no_think'},
        {role:'user',content:chunks[index]},
      ],{max_new_tokens:1400});
      schedule.push(...normalizeLocalSchedule(readLocalJson(output),chunks[index]).schedule);
    }
    return {cardTitle:'Расписание на день',schedule};
  }
  if(action!=='translateText')throw Error('Неизвестная операция локального ИИ.');
  if(!Array.isArray(input.items)||!Array.isArray(input.targetLangs)||input.targetLangs.some(lang=>!languageNames[lang]))throw Error('Выберите языки перевода.');
  const result={},total=input.items.length*input.targetLangs.length;let completed=0;
  for(const item of input.items){
    result[item.id]={};
    for(const language of input.targetLangs){
      if(language==='ru'){result[item.id][language]=item.text;continue;}
      onProgress({message:`Переводим: ${++completed} из ${total}`});
      // Fully specified phrases already have an unambiguous user-approved wording.
      // Longer glossary phrases win over their component words.
      const exact=item.englishContext?null:exactGlossaryTranslation(item.text,language,input.glossary);
      if(exact!==null){result[item.id][language]=exact;continue;}
      const glossary=relevantGlossary(item.text,input.glossary);
      const text=await generate([
        {role:'system',content:`Translate the USER MESSAGE into ${languageNames[language]} for an association football (soccer) club. Output ONLY its translation. No explanation, definitions, JSON or notes. Preserve names, times, formatting and the specificity of every place or activity. A named room keeps its full meaning: конференц-зал means conference room, зал ожидания means waiting lounge, тренировочный зал means gym. Use natural equivalents in the target language. Prefer a specific matching phrase over a general word such as зал. Follow the glossary only when its meaning fits; compare variants in all languages. Respect user-edited English meaning. Reference notes below are NOT part of the message to translate. /no_think\nREFERENCE:\n${JSON.stringify({context:(input.context||'').slice(0,4000),glossary,englishContext:item.englishContext||''})}`},
        {role:'user',content:item.text},
      ],{max_new_tokens:Math.min(700,Math.max(100,item.text.length*2))});
      const translation=String(text).replace(/<think>[\s\S]*?<\/think>/g,'').trim().replace(/^(["“])([\s\S]*)["”]$/,'$2');
      if(!translation||translation.length>6000)throw Error('Модель не смогла перевести событие. Попробуйте ещё раз.');
      result[item.id][language]=translation;
    }
  }
  return result;
}
