// The phone's own «back» (Android's back button or gesture, the browser's back) walks the same way as the on-screen one:
// every screen or window opened on top adds one browser history step, and «back» closes the topmost.
// A step closed on screen takes its history step back with it, so history never holds steps that lead nowhere.
const stack=[];let ignore=0,queued=0,listening=false;

const pop=()=>{
  if(ignore>0){ignore--;if(!ignore)for(;queued;queued--)history.pushState({multischedule:true},'');return;}
  stack.pop()?.();
};

export function pushBack(close){
  if(!listening){addEventListener('popstate',pop);listening=true;}
  const entry=()=>close();stack.push(entry);
  // While an earlier step is still being taken back, a new one waits so it is not taken back too.
  if(ignore)queued++;else history.pushState({multischedule:true},'');
  return entry;
}

export function dropBack(entry){
  const index=stack.lastIndexOf(entry);if(index<0)return;
  let count=stack.length-index;stack.splice(index);
  const waiting=Math.min(queued,count);queued-=waiting;count-=waiting;
  if(count){ignore++;history.go(-count);}
}
