import {useEffect,useRef,useState} from 'react';

// Template cards are edited in place. Typing lands in drafts first and reaches storage after a short pause,
// so a word typed is one undo step rather than one per letter.
export default function useCollectionDrafts(entries,change){
  const [drafts,setDrafts]=useState({}),latest=useRef({entries,change,drafts}),timer=useRef(null);
  latest.current={entries,change,drafts};
  // Any other change to the collection (move, delete, a new entry) is made on top of the drafts and takes them along.
  const commitWith=async(update,retry=false)=>{
    clearTimeout(timer.current);const {entries,change,drafts}=latest.current,ids=Object.keys(drafts);
    const result=await change(update(entries.map(entry=>drafts[entry.id]?{...entry,...drafts[entry.id]}:entry)));
    if(result===false){if(retry)timer.current=setTimeout(flush,300);return false;}
    setDrafts(current=>{const rest={...current};for(const id of ids)if(current[id]===drafts[id])delete rest[id];return rest;});return result;
  };
  const flush=()=>Object.keys(latest.current.drafts).length?commitWith(all=>all,true):Promise.resolve(true);
  const patch=(id,value)=>{setDrafts(current=>({...current,[id]:{...current[id],...value}}));clearTimeout(timer.current);timer.current=setTimeout(flush,700);};
  useEffect(()=>()=>{flush();},[]);
  const view=Object.keys(drafts).length?entries.map(entry=>drafts[entry.id]?{...entry,...drafts[entry.id]}:entry):entries;
  return {view,patch,flush,commitWith,pending:Object.keys(drafts).length>0};
}
