import React from 'react';
import {scheduleRows} from '../services/rows.js';

// Events of one row stand side by side in the picture; everything else keeps its own line.
export function sideBySide(items,nodes){
  let at=0;
  return scheduleRows(items).map(group=>{const part=nodes.slice(at,at+=group.length);return group.length>1?<div key={`row-${group[0].id}`} className="m-export-row">{part}</div>:part[0];});
}
