// A picture block keeps its picture inside the schedule, so a photo from the phone is shrunk to at most 1200 px on its long side.
// Transparent pictures stay PNG; everything else becomes a JPEG.
export async function readPicture(file,max=1200){
  const url=URL.createObjectURL(file);
  try{
    const image=await new Promise((resolve,reject)=>{const node=new Image();node.onload=()=>resolve(node);node.onerror=()=>reject(Error('Не удалось открыть картинку.'));node.src=url;});
    const scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));
    const context=canvas.getContext('2d');context.drawImage(image,0,0,canvas.width,canvas.height);
    let clear=false;
    if(file.type!=='image/jpeg'){const {data}=context.getImageData(0,0,canvas.width,canvas.height);for(let index=3;index<data.length;index+=4)if(data[index]<255){clear=true;break;}}
    return clear?canvas.toDataURL('image/png'):canvas.toDataURL('image/jpeg',.85);
  }finally{URL.revokeObjectURL(url);}
}
