import {useEffect,useRef} from 'react';

// Holding a finger on an empty part of a page (or right-clicking it) opens that page's menu at the finger.
// Cards, buttons, fields, the bottom bars and open sheets keep their own gestures; moving the finger or scrolling cancels.
const BUSY='button,a,input,textarea,select,label,[role=button],[role=slider],[role=listbox],[role=menu],[role=dialog],[contenteditable],[data-event-id],[data-drop-id],.m-bottom-nav,.m-dock-origin,.m-week-strip,.m-tab-menu-layer,.m-event-layer,.m-action-notice';
const HOLD=500,SLOP=10;
export default function useEmptyHold(active,onHold){
  const latest=useRef(onHold);latest.current=onHold;
  useEffect(()=>{
    if(!active)return;
    let press=null;
    const empty=target=>target instanceof Element&&!!target.closest('.m-app')&&!target.closest(BUSY);
    const anchor=(x,y)=>({left:x-1,top:y-1,width:2,height:2});
    const cancel=()=>{if(press){clearTimeout(press.timer);press=null;}};
    const down=event=>{
      cancel();if(event.button!==0||!event.isPrimary||!empty(event.target))return;
      const {clientX:x,clientY:y,pointerId}=event;
      press={x,y,timer:setTimeout(()=>{press=null;navigator.vibrate?.(10);suppress=Date.now()+600;latest.current(anchor(x,y),pointerId);},HOLD)};
    };
    const move=event=>{if(press&&Math.hypot(event.clientX-press.x,event.clientY-press.y)>SLOP)cancel();};
    let suppress=0;
    const click=event=>{if(Date.now()<suppress){event.preventDefault();event.stopPropagation();}};
    const menu=event=>{if(Date.now()<suppress){event.preventDefault();return;}if(event.pointerType==='touch'||!empty(event.target))return;event.preventDefault();cancel();latest.current(anchor(event.clientX,event.clientY),null);};
    document.addEventListener('pointerdown',down);document.addEventListener('pointermove',move);document.addEventListener('pointerup',cancel);document.addEventListener('pointercancel',cancel);
    window.addEventListener('scroll',cancel,true);document.addEventListener('click',click,true);document.addEventListener('contextmenu',menu);
    return()=>{cancel();document.removeEventListener('pointerdown',down);document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',cancel);document.removeEventListener('pointercancel',cancel);
      window.removeEventListener('scroll',cancel,true);document.removeEventListener('click',click,true);document.removeEventListener('contextmenu',menu);};
  },[active]);
}
