import {moveScheduleItem} from './editor.js';

// Events standing side by side share a `row` id. A row is always one unbroken run of two or more events:
// a run cut in two becomes two rows, and an event left alone in its row stands by itself again.
const newRow=()=>globalThis.crypto?.randomUUID?.()||`row-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const withoutRow=item=>{const {row,...rest}=item;return rest;};

export function normalizeRows(items){
  const seen=new Set();let run=null;
  const rows=items.map((item,index)=>{if(!item.row){run=null;return null;}if(run&&items[index-1]?.row===item.row)return run;run=seen.has(item.row)?newRow():item.row;seen.add(run);return run;});
  let changed=false;
  const result=items.map((item,index)=>{const row=rows[index],alone=row&&rows[index-1]!==row&&rows[index+1]!==row,next=row&&!alone?row:undefined;if(next===item.row||(!next&&!item.row))return item;changed=true;return next?{...item,row:next}:withoutRow(item);});
  return changed?result:items;
}

// Consecutive events of one row, in order; every other event is a group of its own.
export function scheduleRows(items){
  const groups=[];
  for(const item of items){const last=groups.at(-1);if(item.row&&last?.[0].row===item.row)last.push(item);else groups.push([item]);}
  return groups;
}

// Dropped beside another event («left»/«right») it joins that event's row; above or below («before»/«after») it stands alone next to the target's whole row.
export function placeItem(items,id,{id:targetId,side}){
  const item=items.find(entry=>entry.id===id);if(id===targetId||!item||!items.some(entry=>entry.id===targetId))return items;
  const rest=normalizeRows(items.filter(entry=>entry.id!==id)),target=rest.find(entry=>entry.id===targetId);
  if(side==='left'||side==='right'){
    const row=target.row||newRow(),list=rest.map(entry=>entry.id===targetId?{...entry,row}:entry),at=list.findIndex(entry=>entry.id===targetId)+(side==='right'?1:0);
    return normalizeRows([...list.slice(0,at),{...item,row},...list.slice(at)]);
  }
  let at=rest.indexOf(target);
  if(side==='before')while(target.row&&rest[at-1]?.row===target.row)at--;
  else {while(target.row&&rest[at+1]?.row===target.row)at++;at++;}
  return normalizeRows([...rest.slice(0,at),withoutRow(item),...rest.slice(at)]);
}

// Moved up or down among the others, an event leaves its row.
export function moveApart(items,id,target){
  const moved=moveScheduleItem(items,id,target);if(moved===items)return items;
  return normalizeRows(moved.map(entry=>entry.id===id&&entry.row?withoutRow(entry):entry));
}

// The ids of the group an event stands in (just its own id when it stands alone).
export function groupIds(items,id){return (scheduleRows(items).find(group=>group.some(item=>item.id===id))||[]).map(item=>item.id);}
export function removeItems(items,ids){const gone=new Set(ids);return normalizeRows(items.filter(item=>!gone.has(item.id)));}
// A whole group copied stands as a new group of its own right under it.
export function copyGroup(items,ids){const set=new Set(ids),last=items.reduce((at,item,index)=>set.has(item.id)?index:at,-1);if(last<0)return items;const row=newRow(),copies=items.filter(item=>set.has(item.id)).map(item=>({...structuredClone(item),id:globalThis.crypto?.randomUUID?.()||`${item.id}-copy-${Math.random().toString(36).slice(2)}`,...(ids.length>1?{row}:{})}));return normalizeRows([...items.slice(0,last+1),...copies,...items.slice(last+1)]);}
