import React,{useEffect,useState} from 'react';
import CenteredModal,{SheetNav} from './CenteredModal.jsx';

// Width and height use the number keyboard, stay as typed until the field is left, and are then held to 320–7680 px.
function SizeField({label,value,onCommit}){
  const [text,setText]=useState(String(value||''));useEffect(()=>setText(String(value||'')),[value]);
  const commit=()=>{const number=Math.round(Number(text));if(!text.trim()||!Number.isFinite(number)){setText(String(value||''));return;}const clamped=Math.max(320,Math.min(7680,number));setText(String(clamped));if(clamped!==value)onCommit(clamped);};
  return <label className="m-field">{label}, px<input inputMode="numeric" enterKeyHint="done" pattern="[0-9]*" value={text} onChange={event=>setText(event.target.value.replace(/[^\d]/g,'').slice(0,4))} onBlur={commit} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();event.currentTarget.blur();}}}/></label>;
}

export default function SizeTemplateEditor({value,onChange,onClose,onSave,onApply,busy,folderControl}){
  const update=patch=>onChange({...value,...patch});
  return <CenteredModal label="Масштаб изображения" onClose={onClose} className="m-template-dialog"><form onSubmit={event=>{event.preventDefault();onSave();}}>
    <SheetNav title="Масштаб" onCancel={onClose} disabled={busy}/><div className="m-modal-body">
      <label className="m-field">Название<input required maxLength={100} enterKeyHint="next" value={value.name} onChange={event=>update({name:event.target.value})}/></label>
      <div className="m-size-fields"><SizeField label="Ширина" value={value.width} onCommit={width=>update({width})}/><SizeField label="Высота" value={value.height} onCommit={height=>update({height})}/></div>
      {folderControl}
    </div><div className="m-modal-footer"><button className="m-secondary m-sheet-apply" type="button" onClick={onApply} disabled={busy||!value.width||!value.height}>Применить к картинке</button></div>
  </form></CenteredModal>;
}
