import React,{useState,useEffect,useRef} from 'react';
import FolderSelect from './FolderSelect.jsx';
import EditorIcon from './EditorIcon.jsx';
import BackBar from './BackBar.jsx';
import useBackClose from './useBackClose.js';
import SlidingTabs from './SlidingTabs.jsx';
import GestureList from './GestureList.jsx';
import ActionDock from './ActionDock.jsx';
import CenteredModal,{SheetNav} from './CenteredModal.jsx';
import InlineCard from './InlineCard.jsx';
import TranslationTemplates from './TranslationTemplates.jsx';
import SizeTemplateEditor from './SizeTemplateEditor.jsx';
import DayTemplateEditor from './DayTemplateEditor.jsx';
import TeamTemplateEditor from './TeamTemplateEditor.jsx';
import useCollectionDrafts from './useCollectionDrafts.js';
import {scheduleKind} from './ScheduleTemplateMenu.jsx';
import {createScheduleItem} from '../services/schedule.js';
import {EVENT_COLORS,eventLabel,eventTime,moveScheduleItem} from '../services/editor.js';
import {dayLabel,reorderSubset,titleIntoSchedule} from '../services/week.js';
import {validImageSize} from '../services/image-sizes.js';
import {ruleLanguage,ruleTranslation} from '../services/glossary.js';
import useEmptyHold from './useEmptyHold.js';
import {isFolder,folderContents,moveIntoFolder,swipeTemplateBranch,clearFolder,branchIds} from '../services/template-folders.js';

const countLabel=(n,one,few,many)=>`${n} ${n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many}`;
const TABS=[{value:'events',label:'События'},{value:'schedules',label:'Расписания'},{value:'translations',label:'Перевод'},{value:'teams',label:'Команды'},{value:'sizes',label:'Масштаб'}];

// One kind of template. Events are cards like the schedule's own, edited in place;
// schedules, translations, teams and sizes open their editor. Drafts of typed text are saved after a pause, and every other change carries them along.
function TemplateRows({tab,entries,parentId,change,commitRef,perform,blocked,header,textId,onTextId,onOpen,onUseEvent,targetDay,teams,Icon,iconNames,languages,availableLanguages}){
  const drafts=useCollectionDrafts(entries,change);commitRef.current=drafts.commitWith;
  const items=folderContents(drafts.view,parentId),events=drafts.view.filter(entry=>!isFolder(entry));
  const move=(id,target)=>perform(()=>drafts.commitWith(all=>reorderSubset(all,folderContents(all,parentId),id,target,moveScheduleItem)),null);
  const dropInto=(id,target)=>perform(()=>drafts.commitWith(all=>moveIntoFolder(all,id,target)),'Перемещено в папку');
  const swipe=(id,action)=>perform(()=>drafts.commitWith(all=>swipeTemplateBranch(all,id,action)),action==='delete'?'Удалено':'Скопировано');
  const label=entry=>isFolder(entry)?entry.name:tab==='translations'?`${entry.source} → ${ruleTranslation(entry)}`:entry.name||entry.cardTitle;
  const note=entry=>tab==='schedules'?`${scheduleKind(entry)} · ${countLabel(entry.schedule?.length||0,'событие','события','событий')}`:tab==='translations'?[availableLanguages.find(language=>language.code===ruleLanguage(entry))?.name,entry.context].filter(Boolean).join(' · '):tab==='sizes'?`${entry.width} × ${entry.height} px`:'';
  const row=(entry,handle)=><div data-folder-target={isFolder(entry)?entry.id:undefined} className={`m-library-row m-preset-row ${entry.enabled===false?'is-disabled':''}`}>
    <button type="button" className="m-preset-open" aria-label={`${isFolder(entry)?'Открыть папку':'Открыть шаблон'} ${label(entry)}`} onClick={()=>onOpen(entry)}>
      <span className="m-preset-icon">{isFolder(entry)?<EditorIcon name="folder"/>:tab==='teams'&&entry.image?<img draggable={false} src={entry.image} alt=""/>:<EditorIcon name={tab==='teams'?'shield':tab==='translations'?'translate':tab==='sizes'?'resize':'schedule'}/>}</span>
      <span>{label(entry)}{isFolder(entry)?<small>{countLabel(branchIds(drafts.view,entry.id).size-1,'элемент','элемента','элементов')}</small>:note(entry)&&<small>{note(entry)}</small>}</span>
    </button>
    {tab==='translations'&&!isFolder(entry)&&<label data-no-drag className="m-rule-toggle"><input type="checkbox" role="switch" aria-label={`Включить правило ${entry.source}`} checked={entry.enabled!==false} onChange={event=>perform(()=>drafts.commitWith(all=>all.map(value=>value.id===entry.id?{...value,enabled:event.target.checked}:value)),null)}/></label>}
    {isFolder(entry)&&<span className="m-folder-arrow" aria-hidden="true">›</span>}{handle}
  </div>;
  const card=(entry,handle)=>{
    if(isFolder(entry)||tab!=='events')return row(entry,handle);
    const patch=value=>drafts.patch(entry.id,value);
    return <InlineCard item={entry} items={events} editingText={textId===entry.id} onPatch={patch} onBeginEdit={()=>{}} onText={()=>onTextId(entry.id)} onTextDone={()=>onTextId(null)} Icon={Icon} iconNames={iconNames} languages={languages} availableLanguages={availableLanguages} teams={teams} handle={handle}
      aside={<button type="button" className="m-inline-aside" aria-label={targetDay?`Добавить: ${dayLabel(targetDay)}`:`Добавить в расписание: ${eventLabel(entry)}`} onClick={()=>drafts.flush().then(()=>onUseEvent(entry))}><EditorIcon name="plus"/></button>}/>;
  };
  return <><GestureList key={`${tab}:${parentId}`} className="m-library m-template-tree" items={items} enabled={!blocked&&!textId} onMove={move} onSwipe={swipe} onDropInto={dropInto} header={header}>{card}</GestureList>{!items.length&&<p className="m-empty-day">Нет шаблонов</p>}</>;
}

export default function TemplateLibrary({collections,changes,histories,targetDay,navigation,onNavigation,state,Icon,iconNames,languages,availableLanguages,onBack,onUseEvent,onUseSchedule,onUseSize,onSaveEvent,onSaveSchedule,onBookmarkEvent,perform,busy}){
  const {tab,folders={}}=navigation,entries=collections[tab],change=changes[tab],history=histories[tab];
  const folder=entries.find(entry=>entry.id===folders[tab]&&isFolder(entry)),parentId=folder?.id||null;
  const commitRef=useRef(async update=>change(update(entries)));
  const [ruleDraft,setRuleDraft]=useState(null),[sizeError,setSizeError]=useState(''),[choice,setChoice]=useState(false),[folderDraft,setFolderDraft]=useState(null),[draft,setDraft]=useState(null),[saveModal,setSaveModal]=useState(null),[name,setName]=useState(state.cardTitle||'Расписание'),[destination,setDestination]=useState(parentId),[textId,setTextId]=useState(null);
  const blocked=busy||!!choice||!!folderDraft||!!draft||!!saveModal||!!ruleDraft;
  // Holding empty space offers what the «+» offers.
  useEmptyHold(!blocked&&!textId,()=>setChoice(true));
  const navigate=id=>{onNavigation({...navigation,folders:{...folders,[tab]:id||null}});window.scrollTo({top:0,behavior:'instant'});};
  const back=()=>{if(folder)navigate(folder.parentId);};
  useBackClose(back,!!folder,folder?.id);
  useEffect(()=>{if(folders[tab]&&!folder)navigate(null);},[entries,tab]);
  useEffect(()=>setTextId(null),[tab]);
  const saveDraft=()=>{if(draft.kind==='size'&&!validImageSize(draft.value)){setSizeError('Укажите ширину и высоту от 320 до 7680 пикселей.');return;}setSizeError('');perform(async()=>{const value=draft.value;if(await commitRef.current(all=>all.some(entry=>entry.id===value.id)?all.map(entry=>entry.id===value.id?value:entry):[...all,value])!==false)setDraft(null);},'Шаблон сохранён');};
  // An older day template shows its title and date as the events they now are.
  const open=entry=>{if(isFolder(entry)){navigate(entry.id);return;}const value=tab==='schedules'&&entry.scheduleMode!=='week'&&!entry.titleInSchedule?{...structuredClone(entry),schedule:titleIntoSchedule(entry.schedule,entry),titleInSchedule:true}:structuredClone(entry);if(tab==='translations'){setRuleDraft(structuredClone(entry));return;}setSizeError('');setDraft({kind:tab==='teams'?'team':tab==='sizes'?'size':'day',value});};
  // A new event appears as an empty card in place, ready to fill in.
  const addCard=value=>perform(async()=>{if(await commitRef.current(all=>[...all,value])!==false&&tab==='events')setTextId(value.id);},null);
  const addTemplate=()=>{setDestination(parentId);setChoice(false);if(tab==='events')setSaveModal('event');else if(tab==='schedules'){setName(state.cardTitle||'Расписание');setSaveModal('schedule');}else if(tab==='translations')setRuleDraft({id:crypto.randomUUID(),parentId,source:'',translation:'',language:'en',context:'',enabled:true});else if(tab==='sizes'){setSizeError('');setDraft({kind:'size',value:{id:crypto.randomUUID(),parentId,name:'Новый масштаб',width:Math.round((state.exportWidth||896)*2),height:Math.round((state.exportHeight||630)*2)}});}else setDraft({kind:'team',value:{id:crypto.randomUUID(),parentId,name:'',image:null}});};
  // Inside a folder a dragged template can be carried out to the folder above; the place for that shows only while dragging.
  const parentName=folder?entries.find(entry=>entry.id===folder.parentId)?.name||'Шаблоны':'';
  const folderHeader=folder?<div data-folder-target={folder.parentId||''} data-no-drag className="m-parent-drop" aria-hidden="true"><EditorIcon name="back"/><span>Вынести в «{parentName}»</span></div>:null;
  const withDrafts=action=>async()=>{await commitRef.current(all=>all);return action();};
  return <>
    <div inert={blocked}>{folder&&<BackBar label={parentName} onBack={back}/>}
      <h1 aria-label={folder?.name} className={folder?undefined:'m-tab-title'}>{folder?<button type="button" className="m-folder-title" aria-label="Переименовать папку" onClick={()=>setFolderDraft({...folder})}>{folder.name}</button>:'Шаблоны'}</h1>
      <SlidingTabs className="m-library-tabs" label="Виды шаблонов" value={tab} onChange={tab=>onNavigation({...navigation,tab})} items={TABS}/>
      {targetDay&&<p className="m-template-target">Добавление: {dayLabel(targetDay)}. Нажмите «+» на карточке события или откройте шаблон расписания.</p>}
      <TemplateRows key={tab} tab={tab} entries={entries} parentId={parentId} change={change} commitRef={commitRef} perform={perform} blocked={blocked} header={folderHeader} textId={textId} onTextId={setTextId} onOpen={open} onUseEvent={onUseEvent} targetDay={targetDay} teams={collections.teams} Icon={Icon} iconNames={iconNames} languages={languages} availableLanguages={availableLanguages}/>
    </div>
    <ActionDock disabled={blocked||history.pending} canUndo={history.canUndo} canRedo={history.canRedo} onUndo={()=>perform(withDrafts(history.undo),'Действие отменено')} onRedo={()=>perform(withDrafts(history.redo),'Действие возвращено')} onClear={()=>perform(()=>commitRef.current(all=>clearFolder(all,parentId)),'Содержимое очищено')} label="Создать" onCreate={()=>setChoice(true)}/>
    {choice&&<CenteredModal label="Создать" onClose={()=>setChoice(false)} className="m-template-dialog"><SheetNav title="Создать" onCancel={()=>setChoice(false)} action={null}/><div className="m-modal-body"><button type="button" className="m-template-select" onClick={()=>{setChoice(false);setFolderDraft({id:crypto.randomUUID(),kind:'folder',name:'',parentId});}}><EditorIcon name="folder"/>Папка</button><button type="button" className="m-template-select" onClick={addTemplate}><EditorIcon name="bookmark"/>Шаблон</button></div></CenteredModal>}
    {folderDraft&&<CenteredModal label="Папка шаблонов" onClose={()=>setFolderDraft(null)} className="m-template-dialog"><form onSubmit={event=>{event.preventDefault();const value={...folderDraft,name:folderDraft.name.trim()};if(!value.name)return;perform(async()=>{if(await commitRef.current(all=>all.some(entry=>entry.id===value.id)?all.map(entry=>entry.id===value.id?value:entry):[...all,value])!==false)setFolderDraft(null);},'Папка сохранена');}}><SheetNav title="Папка" onCancel={()=>setFolderDraft(null)} disabled={busy||!folderDraft.name.trim()}/><div className="m-modal-body"><label className="m-field">Название папки<input autoFocus required maxLength={100} value={folderDraft.name} onChange={event=>setFolderDraft(current=>({...current,name:event.target.value}))}/></label></div></form></CenteredModal>}
    {saveModal==='event'&&<CenteredModal label="Выберите событие" onClose={()=>setSaveModal(null)} className="m-template-dialog"><SheetNav title="Шаблон события" onCancel={()=>setSaveModal(null)} action={null}/><div className="m-modal-body"><FolderSelect entries={collections.events} value={destination} onChange={setDestination}/><button type="button" className="m-template-select" onClick={()=>{setSaveModal(null);addCard(createScheduleItem({description:'',parentId:destination}));}}><EditorIcon name="plus"/>Новое событие</button>{state.schedule.filter(item=>item.description?.trim()||item.type==='game'&&(item.homeTeam?.name||item.awayTeam?.name)).map(item=><button type="button" key={item.id} className="m-template-select" style={{background:EVENT_COLORS[item.color]?.[1]||'#fff'}} onClick={()=>perform(async()=>{await commitRef.current(all=>all);if(await onSaveEvent(item,destination)!==false)setSaveModal(null);},'Событие сохранено в шаблоны')}>{item.type!=='game'&&<Icon icon={item.icon}/>}<span>{eventLabel(item)}{eventTime(item)&&<small>{eventTime(item)}</small>}</span></button>)}</div></CenteredModal>}
    {saveModal==='schedule'&&<CenteredModal label="Сохранить шаблон расписания" onClose={()=>setSaveModal(null)} className="m-template-dialog"><form onSubmit={event=>{event.preventDefault();perform(async()=>{if(await onSaveSchedule(name,destination)!==false)setSaveModal(null);},'Расписание сохранено в шаблоны');}}><SheetNav title="Шаблон расписания" onCancel={()=>setSaveModal(null)} disabled={busy||!name.trim()}/><div className="m-modal-body"><label className="m-field">Название<input autoFocus required value={name} onChange={event=>setName(event.target.value)}/></label><FolderSelect entries={collections.schedules} value={destination} onChange={setDestination}/></div></form></CenteredModal>}
    {draft?.kind==='day'&&<DayTemplateEditor folderControl={<FolderSelect entries={collections.schedules} value={draft.value.parentId} onChange={parentId=>setDraft(current=>({...current,value:{...current.value,parentId}}))}/>}  value={draft.value} onChange={change=>setDraft(current=>({...current,value:change(current.value)}))} onClose={()=>setDraft(null)} onSave={saveDraft} busy={busy} Icon={Icon} iconNames={iconNames} teams={collections.teams} languages={draft.value.selectedLanguages||[]} availableLanguages={availableLanguages} applyLabel={targetDay?`Добавить: ${dayLabel(targetDay)}`:state.scheduleMode==='week'&&draft.value.scheduleMode!=='week'?'Добавить день в неделю':'Добавить в расписание'} onApply={()=>{onUseSchedule(draft.value);setDraft(null);}}/>}
    {sizeError&&draft?.kind==='size'&&<div className="m-action-notice" role="alert">{sizeError}</div>}
    {draft?.kind==='size'&&<SizeTemplateEditor folderControl={<FolderSelect entries={collections.sizes} value={draft.value.parentId} onChange={parentId=>setDraft(current=>({...current,value:{...current.value,parentId}}))}/>} value={draft.value} onChange={value=>{setSizeError('');setDraft(current=>({...current,value}));}} onClose={()=>setDraft(null)} onSave={saveDraft} busy={busy} onApply={()=>{if(!validImageSize(draft.value)){setSizeError('Укажите ширину и высоту от 320 до 7680 пикселей.');return;}onUseSize(draft.value);setDraft(null);}}/>}
    <TranslationTemplates folderControl={ruleDraft?<FolderSelect entries={collections.translations} value={ruleDraft.parentId} onChange={parentId=>setRuleDraft(current=>({...current,parentId}))}/>:null} templates={tab==='translations'?entries:collections.translations} onChange={next=>commitRef.current(()=>next)} perform={perform} busy={busy} draft={ruleDraft} onDraftChange={setRuleDraft} availableLanguages={availableLanguages}/>
    {draft?.kind==='team'&&<TeamTemplateEditor folderControl={<FolderSelect entries={collections.teams} value={draft.value.parentId} onChange={parentId=>setDraft(current=>({...current,value:{...current.value,parentId}}))}/>}  value={draft.value} onChange={value=>setDraft(current=>({...current,value}))} onClose={()=>setDraft(null)} onSave={saveDraft} busy={busy}/>}
  </>;
}
