import React,{useRef} from 'react';

// The notice at the top follows a finger upwards: pushed up far or fast enough it leaves, otherwise it springs back.
// Pulled down it only gives a little, like a sheet at its end.
export default function ActionNotice({className='',onDismiss,children,...props}){
  const node=useRef(null),drag=useRef(null);
  const place=(y,animate)=>{const el=node.current;if(!el)return;el.style.transition=animate?'translate 180ms ease, opacity 180ms ease':'none';el.style.translate=`0 ${y}px`;el.style.opacity=String(Math.max(0,1+Math.min(0,y)/60));};
  const down=event=>{if(event.button>0||event.target.closest('button'))return;drag.current={id:event.pointerId,y:event.clientY,dy:0,at:performance.now(),speed:0};try{event.currentTarget.setPointerCapture(event.pointerId);}catch{}};
  const move=event=>{const at=drag.current;if(!at||event.pointerId!==at.id)return;const raw=event.clientY-at.y,dy=raw<0?raw:raw*.2,now=performance.now();
    at.speed=(at.dy-dy)/Math.max(1,now-at.at);at.dy=dy;at.at=now;place(dy,false);};
  const up=event=>{const at=drag.current;if(!at||event.pointerId!==at.id)return;drag.current=null;
    if(at.dy<-24||(at.speed>.5&&at.dy<-8)){place(-120,true);setTimeout(onDismiss,170);}else place(0,true);};
  return <div ref={node} className={`m-action-notice is-swipeable ${className}`} onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up} {...props}>{children}</div>;
}
