import React,{useId,useState,useRef,useEffect} from 'react';
import EditorIcon from './EditorIcon.jsx';
import {teamSuggestions,typeTeamName} from '../services/editor.js';

export default function TeamFields({value={},onChange,label='Команда',teams=[],onBusyChange}){
  const id=useId(),[error,setError]=useState(''),[loading,setLoading]=useState(false),[open,setOpen]=useState(false),pending=useRef(null),mounted=useRef(true),latest=useRef(null);latest.current={value,onChange,onBusyChange};
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;pending.current?.abort();};},[]);
  const cancel=()=>{const reader=pending.current;pending.current=null;reader?.abort();setLoading(false);latest.current.onBusyChange?.(false);};
  const upload=event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!file.type.startsWith('image/')){setError('Выберите картинку команды.');return;}cancel();const reader=new FileReader();pending.current=reader;setLoading(true);latest.current.onBusyChange?.(true);reader.onerror=()=>{if(!mounted.current||pending.current!==reader)return;pending.current=null;setLoading(false);latest.current.onBusyChange?.(false);setError('Не удалось прочитать картинку.');};reader.onload=()=>{if(!mounted.current||pending.current!==reader)return;pending.current=null;setLoading(false);setError('');latest.current.onBusyChange?.(false);latest.current.onChange({...latest.current.value,image:reader.result});};reader.readAsDataURL(file);};
  const type=name=>{const next=typeTeamName(value,name,teams);if(next.image!==value.image)cancel();onChange(next);};
  const suggestions=open?teamSuggestions(teams,value.name):[];
  return <fieldset className="m-team-fields"><legend>{label}</legend>
    <div className="m-team-name">
      <span className="m-team-thumb">{value.image?<img draggable={false} src={value.image} alt=""/>:<EditorIcon name="image"/>}</span>
      <input aria-label={`${label}: название`} placeholder="Название команды" autoComplete="off" enterKeyHint="done" role="combobox" aria-expanded={suggestions.length>0} aria-controls={`${id}-list`} value={value.name||''} onFocus={()=>setOpen(true)} onBlur={()=>setOpen(false)} onChange={event=>{setOpen(true);type(event.target.value);}} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();event.currentTarget.blur();}}}/>
    </div>
    {suggestions.length>0&&<div id={`${id}-list`} role="listbox" className="m-team-suggestions">{suggestions.map(team=><button type="button" role="option" aria-selected={false} key={team.id} onPointerDown={event=>event.preventDefault()} onClick={()=>{cancel();onChange({name:team.name,image:team.image||null});setOpen(false);}}>{team.image?<img draggable={false} src={team.image} alt=""/>:<span className="m-team-suggestion-blank"/>}<span>{team.name}</span></button>)}</div>}
    <div className="m-team-image"><label htmlFor={id} className="m-secondary"><EditorIcon name="image"/>{loading?'Загрузка картинки…':value.image?'Заменить картинку':'Своя картинка'}</label><input id={id} type="file" accept="image/*" className="m-picture-input" aria-label={`${label}: картинка`} onChange={upload}/>{value.image&&<button type="button" className="m-icon-button" aria-label={`${label}: убрать картинку`} onClick={()=>{cancel();onChange({...value,image:null});}}><EditorIcon name="close"/></button>}</div>
    {error&&<p role="alert" className="m-danger">{error}</p>}
  </fieldset>;
}
