import React,{useImperativeHandle,useLayoutEffect,useRef} from 'react';
import {wheelAppearance,hapticTick} from '../services/wheel.js';
import useMouseDrum from './useMouseDrum.js';

// Native touch scrolling keeps momentum and scroll snapping on mobile browsers; a mouse drags it, clicks a face or turns it notch by notch (useMouseDrum).
// Linked to another scroller: onTrack reports where the user's finger has the wheel (in items, fractional),
// and trackRef.current.track(position) puts it there while the other one is being moved.
export default function WheelPicker({label,items,value,onChange,onSelectedClick,onHold,onTrack,trackRef}){
  const root=useRef(null),latest=useRef({value,onChange}),lastCenter=useRef(value),timer=useRef(null),userScroll=useRef(false);
  latest.current={value,onChange,onTrack};
  const geometry=()=>{const node=root.current,[first,second]=node.children;if(!first)return null;return {node,origin:first.offsetLeft+first.offsetWidth/2,step:second?second.offsetLeft-first.offsetLeft:first.offsetWidth};};
  // Snapping stays off while it is being led, so a finger resting mid-way keeps both where it is; it returns with the next glide to a value or touch.
  useImperativeHandle(trackRef,()=>({track(position){const shape=geometry();if(!shape)return;userScroll.current=false;clearTimeout(timer.current);const {node,origin,step}=shape;clearTimeout(stepped.current?.timer);stepped.current=null;node.style.scrollSnapType='none';node.scrollTo({left:origin+position*step-node.clientWidth/2,behavior:'instant'});}}),[]);
  const center=(index,behavior='smooth')=>{const node=root.current,child=node?.children[index];if(child)node.style.scrollSnapType='';if(child)node.scrollTo({left:child.offsetLeft+child.offsetWidth/2-node.clientWidth/2,behavior});};
  useLayoutEffect(()=>{
    const node=root.current;let frame;const shown=new WeakMap();
    // All reads before any write, and only changed values written, so a scroll frame costs one layout.
    const measure=()=>{const midpoint=node.scrollLeft+node.clientWidth/2,children=Array.from(node.children),distances=children.map(child=>(child.offsetLeft+child.offsetWidth/2-midpoint)/64);let nearest=0;
      distances.forEach((distance,index)=>{if(Math.abs(distance)<Math.abs(distances[nearest]))nearest=index;const look=wheelAppearance(distance),child=children[index],next=`${Math.round(look.scale*1000)/1000} ${Math.round(look.opacity*1000)/1000}`;if(shown.get(child)===next)return;shown.set(child,next);child.style.setProperty('--wheel-scale',look.scale);child.style.setProperty('--wheel-opacity',look.opacity);});return nearest;};
    const scroll=()=>{if(userScroll.current&&hold.current&&!hold.current.fired){clearTimeout(hold.current.timer);hold.current=null;}if(userScroll.current&&latest.current.onTrack){const shape=geometry();if(shape)latest.current.onTrack((node.scrollLeft+node.clientWidth/2-shape.origin)/shape.step);}cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const index=measure();if(lastCenter.current!==items[index]?.value){lastCenter.current=items[index]?.value;hapticTick();}});commitSoon();};
    // The value is taken once the wheel rests with no finger on it, so a finger held still mid-way changes nothing yet.
    const commitSoon=()=>{clearTimeout(timer.current);timer.current=setTimeout(()=>{if(!userScroll.current||touching)return;userScroll.current=false;const index=measure(),next=items[index]?.value;if(next===undefined)return;
      // A wheel that rests off-centre (snapping was off while it was led) is brought onto its face even when the value stays the same.
      if(next!==latest.current.value)latest.current.onChange(next);else center(index);},150);};
    let touching=false;const down=event=>{if(event.type==='touchstart'||event.pointerType==='mouse')touching=true;};const up=event=>{if(event.type!=='pointerup'||event.pointerType==='mouse'){touching=false;commitSoon();}};
    for(const name of ['touchstart','pointerdown'])node.addEventListener(name,down,{passive:true});for(const name of ['touchend','touchcancel','pointerup'])node.addEventListener(name,up,{passive:true});
    const observer=new ResizeObserver(()=>{const i=items.findIndex(entry=>entry.value===latest.current.value);if(i>=0)center(i,'instant');measure();});observer.observe(node);node.addEventListener('scroll',scroll,{passive:true});measure();return()=>{observer.disconnect();node.removeEventListener('scroll',scroll);for(const name of ['touchstart','pointerdown'])node.removeEventListener(name,down);for(const name of ['touchend','touchcancel','pointerup'])node.removeEventListener(name,up);cancelAnimationFrame(frame);clearTimeout(timer.current);};
  },[items.length]);
  // A value set from outside glides there, unless the finger is still on the wheel.
  // Holding a face still for half a second is its own action (a day off, say); moving the finger or scrolling cancels it.
  const hold=useRef(null);
  const holdStart=item=>event=>{if(!onHold||event.button>0)return;clearTimeout(hold.current?.timer);const at={x:event.clientX,y:event.clientY,fired:false};at.timer=setTimeout(()=>{at.fired=true;navigator.vibrate?.(15);onHold(item.value);},480);hold.current=at;};
  const holdMove=event=>{const at=hold.current;if(at&&!at.fired&&Math.hypot(event.clientX-at.x,event.clientY-at.y)>8){clearTimeout(at.timer);hold.current=null;}};
  const holdEnd=()=>{const at=hold.current;if(at&&!at.fired){clearTimeout(at.timer);hold.current=null;}};
  // The mouse lands the wheel on a face itself and takes that face's value at once, so nothing waits for the scrolling to settle.
  const stepped=useRef(null);
  const settleOn=index=>{const at=Math.max(0,Math.min(items.length-1,index));userScroll.current=false;clearTimeout(timer.current);center(at);const next=items[at]?.value;if(next!==undefined&&next!==latest.current.value)latest.current.onChange(next);};
  const nearest=offset=>{const shape=geometry();return shape?Math.round((offset+shape.node.clientWidth/2-shape.origin)/shape.step):0;};
  useMouseDrum(root,{axis:'x',
    onDrag:()=>{userScroll.current=true;clearTimeout(hold.current?.timer);hold.current=null;clearTimeout(stepped.current?.timer);stepped.current=null;},
    onRelease:offset=>settleOn(nearest(offset)),
    // Notches in a row run ahead of the value: the wheel glides face by face, and the value follows once the notches stop.
    onStep:direction=>{const from=stepped.current?stepped.current.index:Math.max(0,items.findIndex(item=>item.value===latest.current.value)),index=Math.max(0,Math.min(items.length-1,from+direction));clearTimeout(stepped.current?.timer);userScroll.current=false;clearTimeout(timer.current);center(index);stepped.current={index,timer:setTimeout(()=>{stepped.current=null;settleOn(index);},220)};},
  });
  const mounted=useRef(false);
  useLayoutEffect(()=>{const index=items.findIndex(item=>item.value===value);if(index>=0&&!userScroll.current)center(index,mounted.current?'smooth':'instant');mounted.current=true;},[value,items.length]);
  return <div className="m-wheel-frame"><div ref={root} className="m-wheel-picker" role="group" aria-label={label}
    onPointerDown={event=>{if(event.pointerType!=='mouse')userScroll.current=true;}}
    onKeyDown={event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();userScroll.current=false;const current=Math.max(0,items.findIndex(item=>item.value===value)),index=event.key==='Home'?0:event.key==='End'?items.length-1:Math.max(0,Math.min(items.length-1,current+(event.key==='ArrowRight'?1:-1)));onChange(items[index].value);root.current.children[index].focus({preventScroll:true});}}
  >{items.map((item,index)=><button type="button" key={item.value} aria-label={item.label} aria-pressed={value===item.value} onPointerDown={holdStart(item)} onPointerMove={holdMove} onPointerUp={holdEnd} onPointerCancel={holdEnd} onPointerLeave={holdEnd} onContextMenu={onHold?event=>event.preventDefault():undefined} onClick={()=>{if(hold.current?.fired){hold.current=null;return;}userScroll.current=false;clearTimeout(timer.current);if(value===item.value&&onSelectedClick)onSelectedClick();else{onChange(item.value);center(index);}}}><span className={`m-wheel-face ${item.className||''}`} style={item.style}>{item.content}</span></button>)}</div><span className="m-wheel-center" aria-hidden="true"/></div>;
}
