export const isFolder=entry=>entry?.kind==='folder';
export const folderParent=entry=>entry?.parentId||null;
export const folderContents=(entries,parentId=null)=>entries.filter(entry=>folderParent(entry)===(parentId||null));
export function folderOptions(entries){
  return entries.filter(isFolder).map(entry=>{const names=[entry.name],seen=new Set([entry.id]);let parent=entry.parentId;while(parent&&!seen.has(parent)){seen.add(parent);const folder=entries.find(value=>value.id===parent&&isFolder(value));if(!folder)break;names.unshift(folder.name);parent=folder.parentId;}return {id:entry.id,label:names.join(' / ')};});
}
export function filterTemplateTree(entries,predicate){
  const ids=new Set(entries.filter(entry=>!isFolder(entry)&&predicate(entry)).map(entry=>entry.id));
  for(const entry of entries)if(ids.has(entry.id)){let parent=entry.parentId,seen=new Set();while(parent&&!seen.has(parent)){seen.add(parent);ids.add(parent);parent=entries.find(value=>value.id===parent)?.parentId;}}
  return entries.filter(entry=>ids.has(entry.id));
}
export function branchIds(entries,id){
  const ids=new Set([id]);let grew=true;
  while(grew){grew=false;for(const entry of entries)if(entry.parentId&&ids.has(entry.parentId)&&!ids.has(entry.id)){ids.add(entry.id);grew=true;}}
  return ids;
}
export function moveIntoFolder(entries,id,parentId){
  const item=entries.find(entry=>entry.id===id),parent=parentId?entries.find(entry=>entry.id===parentId):null;
  if(!item||parentId&&!isFolder(parent))throw Error('Папка назначения не найдена.');
  if(parentId&&branchIds(entries,id).has(parentId))throw Error('Нельзя переместить папку внутрь неё самой.');
  return entries.map(entry=>entry.id===id?{...entry,parentId:parentId||null}:entry);
}
export function swipeTemplateBranch(entries,id,action){
  const ids=branchIds(entries,id);
  if(action==='delete')return entries.filter(entry=>!ids.has(entry.id));
  const mapping=new Map([...ids].map(id=>[id,crypto.randomUUID()]));
  const copied=structuredClone(entries.filter(entry=>ids.has(entry.id))).map(entry=>({...entry,id:mapping.get(entry.id),parentId:mapping.get(entry.parentId)||entry.parentId||null,...(isFolder(entry)&&entry.id===id?{name:entry.name+' (копия)'}:{})}));
  const index=entries.findIndex(entry=>entry.id===id);
  return [...entries.slice(0,index+1),...copied,...entries.slice(index+1)];
}
export function clearFolder(entries,parentId){
  if(!parentId)return [];
  const ids=branchIds(entries,parentId);ids.delete(parentId);return entries.filter(entry=>!ids.has(entry.id));
}
export function validFolderTree(entries){
  const byId=new Map(entries.map(entry=>[entry.id,entry]));if(byId.size!==entries.length)return false;
  for(const entry of entries){let parent=entry.parentId,seen=new Set([entry.id]);while(parent){const node=byId.get(parent);if(!isFolder(node)||seen.has(parent))return false;seen.add(parent);parent=node.parentId;}}
  return true;
}
// Schedules no longer start in the «Дни» and «Недели» folders; each record says whether it is a day or a week.
// Those folders, once created for everyone, are dissolved and their contents moved to the top level.
export async function initializeTemplateFolders(storage){
  const version=storage.getItem('templateFoldersVersion');if(version==='2')return;
  let entries;try{entries=JSON.parse(storage.getItem('savedTemplates')||'[]');}catch{return;}
  if(!Array.isArray(entries))return;
  const preset=new Set(version==='1'?entries.filter(entry=>isFolder(entry)&&!entry.parentId&&['Дни','Недели'].includes(entry.name)).map(entry=>entry.id):[]);
  const next=entries.filter(entry=>!preset.has(entry.id)).map(entry=>preset.has(entry.parentId)?{...entry,parentId:null}:entry);
  await storage.setItems({savedTemplates:JSON.stringify(next),templateFoldersVersion:'2'});
}
