import React from 'react';
import WheelPicker from './WheelPicker.jsx';

const month=day=>new Date(day+'T00:00:00').toLocaleDateString('ru-RU',{month:'short'}).replace('.','').replace(/^./,letter=>letter.toUpperCase());

// The week's days as a horizontal drum: the day under the frame is the one shown, and the month sits above it.
// Holding a day makes it a day off, or a working day again.
// It moves together with the pages (trackRef / onTrack), so either can be dragged.
export default function WeekStrip({days,focus,offDays={},onSelect,onHold,disabled,trackRef,onTrack,className=''}){
  const items=days.map(day=>{const date=new Date(day+'T00:00:00');return {value:day,label:date.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})+(offDays[day]?', выходной':''),className:`m-day-face ${offDays[day]?'is-off':''}`,content:<><small>{date.toLocaleDateString('ru-RU',{weekday:'short'})}</small><span>{date.getDate()}</span></>};});
  // Remount per week so the drum never reports a day from the previous week.
  return <nav className={`m-week-strip ${className}`} aria-label="Дни недели" inert={disabled}><span className="m-week-month" aria-hidden="true">{focus&&month(focus)}</span><WheelPicker key={days[0]} label="День недели" value={focus} onChange={onSelect} onHold={onHold} items={items} trackRef={trackRef} onTrack={onTrack}/></nav>;
}
